            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0x7D973673821954E5ULL) + aOUSaltE[(((511U - aIndex) + 409U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterH) ^ 0x9A7C3206CA3E74B7ULL) ^ aOUSaltB[(((511U - aIndex) + 327U)) & S_SALT1];
