            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0x728648293E837703ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0xF3719F12838B02F5ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x8B38D79C5F575239ULL), 13U);
