            aOrbiterG = (aOrbiterG + aOrbiterB) + 0xA18627DB09BE673CULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x757AECE2AE186D6AULL;
            aOrbiterC = RotL64((aOrbiterC * 0x7C43E7D2522CB3DFULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x4728FDEC6D1C9A72ULL;
