            aOrbiterB = RotL64((aOrbiterB * 0x195E4071CB47C633ULL), 5U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0x305795FBD5FD78FEULL) + aOUSaltB[(((511U - aIndex) + 41U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0xF3DB8F485FA7C49EULL;
            aOrbiterK = RotL64((aOrbiterK * 0x6A0C57BED8AEAB69ULL), 41U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterC) + 0xB8B9D5446981F6EAULL) + aOUSaltC[(((511U - aIndex) + 270U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x375AA0D3D03CEC05ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xBE8911CE27142DE7ULL), 13U);
