            aOrbiterI = (((aWandererI + RotL64(aPrevious, 3U)) + RotL64(aCarry, 57U)) + 0x43E02EA11A15531CULL) + aOASaltE[(((511U - aIndex) + 50U)) & S_SALT1];
            aOrbiterE = ((aWandererK + RotL64(aIngress, 51U)) + RotL64(aCarry, 41U)) + 0xC4838F2C243D1038ULL;
            aOrbiterA = ((aWandererC + RotL64(aCross, 13U)) + 0x4A0AEDDBD3BADC47ULL) + aOASaltD[((aIndex + 341U)) & S_SALT1];
            aOrbiterJ = (((aWandererE + RotL64(aScatter, 57U)) + RotL64(aCarry, 11U)) + 0xB1D93E1C631D82BBULL) + aOASaltF[(((511U - aIndex) + 60U)) & S_SALT1];
