            aOrbiterD = (aWandererI + RotL64(aCross, 19U)) + 0xB2A380E50CE967E3ULL;
            aOrbiterA = (aWandererD + RotL64(aPrevious, 3U)) + 0x20E74771708BA6BFULL;
            aOrbiterE = (((aWandererH + RotL64(aScatter, 12U)) + RotL64(aCarry, 21U)) + 0x0E59812859B6156DULL) + aOASaltG[(((511U - aIndex) + 73U)) & S_SALT1];
            aOrbiterG = ((aWandererG + RotL64(aIngress, 41U)) + 0x5D47128CD1F19D2BULL) + aOASaltC[((aIndex + 493U)) & S_SALT1];
